#!/usr/bin/env python3
"""Independent final product-input review; does not execute BSP or make."""
from pathlib import Path
from collections import Counter, defaultdict
import hashlib, json, re, xml.etree.ElementTree as ET
B=Path('/workspace/build01-product-next');T=B/'product-graph/tree';P=B/'profile/rk322x_sd_box';R=B/'review';E=B/'product-graph/evidence';F=E/'vortex_rk322x_sd_box'
def digest(p): return hashlib.sha256(p.read_bytes()).hexdigest()
def record(p):return {'path':str(p),'bytes':p.stat().st_size,'sha256':digest(p)}
def vals(name):return [s.strip() for s in (F/(name+'.list')).read_text().splitlines() if s.strip()]
packages=vals('packages');counts=Counter(packages);copies=vals('copy-files');config=dict(s.split('=',1) for s in vals('config-values'));overlays=vals('overlays')
required=['VortexHome','DefaultContainerService','Settings','SystemUI','InputDevices','LatinIME','DocumentsUI','ExternalStorageProvider','PackageInstaller','SettingsProvider','framework-res','ethernet-service','wifi-service','gralloc.rk30board','hwcomposer.rk30board','libion','audio.primary.rk30board','audio.usb.default','audio.r_submix.default','power.default']
assert all(counts[k] for k in required)
forbidden=['Launcher','Launcher2','Launcher3','TvLauncher','Bluetooth','BluetoothMidiService','SetupWizard','Provision','recovery','uncrypt','applypatch','gralloc.default','audio_policy.rk30board'];assert not set(forbidden).intersection(packages)
copy_details=[];bydest=defaultdict(list)
for line in copies:
 source,dest,*owner=line.split(':');assert not dest.startswith('/');assert '..' not in Path(source).parts and '..' not in Path(dest).parts
 path=T/source;assert path.is_file();bydest[dest].append(source)
 copy_details.append({'entry':line,'resolved_source':str(path.resolve()),'source_sha256':digest(path),'source_bytes':path.stat().st_size})
assert all(len(set(x))==1 for x in bydest.values());assert len(bydest)==13
assert not any(re.search(r'bluetooth|a2dp|\.hcd$|rtkbt|google|gralloc\.rk30board\.so|hwcomposer\.rk30board\.so|libion\.so',x,re.I) for x in copies)
assert any(x.endswith(':system/etc/fonts.xml') for x in copies)
profile=[]
for p in sorted(P.rglob('*')):
 if p.is_file():
  q=T/'device/vortex/rk322x_sd_box'/p.relative_to(P);assert q.is_file() and p.read_bytes()==q.read_bytes();profile.append({'relative_path':str(p.relative_to(P)),'sha256':digest(p),'bytes':p.stat().st_size,'materialized_tree_matches':True})
assert overlays==['device/vortex/rk322x_sd_box/overlay']
ov=P/'overlay/frameworks/base/packages/SettingsProvider/res/values/defaults.xml';defs={x.attrib['name']:x.text for x in ET.parse(ov).getroot()};assert defs=={'def_device_provisioned':'true','def_user_setup_complete':'true'}
empty=['TARGET_RELEASETOOLS_EXTENSIONS','BOARD_CONNECTIVITY_VENDOR','BOARD_CONNECTIVITY_MODULE','BOARD_WLAN_DEVICE','BOARD_WPA_SUPPLICANT_PRIVATE_LIB','BOARD_HOSTAPD_PRIVATE_LIB','WIFI_DRIVER_FW_PATH_PARAM','WIFI_DRIVER_FW_PATH_STA','WIFI_DRIVER_FW_PATH_P2P','WIFI_DRIVER_FW_PATH_AP']
false=['TARGET_ROCHCHIP_RECOVERY','TARGET_ROCKCHIP_PCBATEST','RECOVERY_AUTO_USB_UPDATE','ENABLE_KEYBOX_PROVISION','BLUETOOTH_USE_BPLUS','BOARD_HAVE_BLUETOOTH_BCM','BOARD_HAVE_BLUETOOTH','BUILD_WITH_DRMSERVICE','BUILD_WITH_GOOGLE_MARKET','BUILD_BOX_WITH_GOOGLE_MARKET','BUILD_WITH_GOOGLE_MARKET_ALL','BUILD_WITH_GOOGLE_FRP']
assert all(k in config and config[k]=='' for k in empty);assert all(config.get(k)=='false' for k in false);assert config['TARGET_NO_RECOVERY']=='true'
stock=[]
for n in ['packages','copy-files','properties']:
 a=E/('baseline-05-'+n+'.list');b=E/'rk322x_box'/(n+'.list');assert a.read_bytes()==b.read_bytes();stock.append({'list':n,'bytes_identical':True,'sha256':digest(a)})
audio=(P/'audio_policy.vortex-sd-reference.conf').read_text();assert not re.search(r'a2dp|bluetooth|sco','\n'.join(x.split('#',1)[0] for x in audio.splitlines()),re.I)
report={'scope':'Independent final resolved product-input review only. Not complete Android module graph, image, runtime or physical-board approval.','inputs':{n:record(F/(n+'.list')) for n in ['packages','copy-files','properties','config-values','overlays']},'counts':{'package_entries':len(packages),'unique_packages':len(counts),'font_package_entries':sum(x.endswith(('.ttf','.ttc')) for x in packages),'copy_entries':len(copies),'unique_copy_destinations':len(bydest),'profile_files_recursive':len(profile),'config_values':len(config)},'required_packages':{x:counts[x] for x in required},'forbidden_exact_packages_selected':[],'copies':copy_details,'profile_files':profile,'overlays':overlays,'config_values':config,'stock_baseline_05_regression':stock,'confirmed_changes':['Only VortexHome selected as HOME launcher package; no stock Launcher/Provision/SetupWizard selected.','13 copy sources are regular files and all destinations are unique relative paths.','SettingsProvider overlay has only two verified bools true; pinned-source reader correspondence in provisioning/.','Audio policy has no active A2DP/SCO/Bluetooth routes.','No inherited Broadcom selector remains populated; this is not Wi-Fi driver identification.','Stock rk322x_box three raw resolved lists remain byte-identical to unpatched baseline-05.'],'open_before_image_or_boot':[{'id':'mount_failure_recovery_bcb','fact':'Actual init/builtins.cpp can call wipe_data_via_recovery for FS_MGR_MNTALL_DEV_NEEDS_RECOVERY; it constructs --wipe_data, writes BCB and requests reboot. Removing recovery/uncrypt/applypatch packages does not remove this compiled init path. Current SD fstab still contains check/encryptable. Exact BCB device resolution, malformed-media behavior and internal-storage preservation need integration review/tests. No assertion that this branch was executed or wrote the physical device.'},{'id':'usb_vold_paths','fact':'SD fstab retains /devices/ff580000.usb*, ff5c0000, ff5d0000 and /devices/usb*, while pinned RK322x DTS USB controllers use addresses30040000,30080000,300a0000,300c0000,300e0000,30100000,30120000. Actual kernel uevent/vold matching must be traced before claiming USB media discovery; DocumentsUI packages alone do not prove it.'},{'id':'device_permissions_selinux','fact':'Minimal board init only mounts the SD fstab when ro.bootmode=sd; vendor graphics device-node ownership, ueventd/SELinux, services and full mount ordering are not integrated.'},{'id':'full_source_module_graph','fact':'Diagnostic tree supplies actual font product fragments, not all font payload/module sources; parsed lists do not prove framework/audio/HAL/application dependencies or image closure.'},{'id':'firstboot_runtime','fact':'Pinned resource/reader checks support the dedicated SettingsProvider overlay, but no SettingsProvider build or fresh Android boot has exercised it.'},{'id':'board_kernel_monitor','fact':'R329Q_V8.0 Wi-Fi, board wiring/DDR and monitor/kernel/DTB interfaces remain unvalidated on physical hardware.'}]}
(R/'final-profile-review.json').write_text(json.dumps(report,indent=2)+'\n')
md=['# Revisão independente final do perfil SD','','Revisão limitada a entradas resolvidas e fontes presentes na árvore diagnóstica. Não aprova uma imagem Android/SD nem a placa física.','',f"Foram conferidas {len(packages)} entradas de pacote ({len(counts)} únicas, incluindo {report['counts']['font_package_entries']} fontes), {len(copies)} cópias com destinos relativos únicos e {len(profile)} arquivos do perfil recursivamente idênticos à árvore materializada.",'','VortexHome é a única seleção de launcher HOME. Estão presentes componentes para Settings/SystemUI, instalação de APK e seleção de arquivos. Os pacotes factory launcher, Bluetooth, GApps, Provision/SetupWizard, recovery, uncrypt, applypatch e gralloc.default não são selecionados. Isso não demonstra drivers ou módulos fechados.','','O overlay SettingsProvider define somente os dois bools verificados por fonte: def_device_provisioned e def_user_setup_complete. Ele se aplica a dados novos; seu primeiro boot ainda não foi executado.','','As três listas brutas de rk322x_box são byte a byte iguais ao baseline-05 sem patch, usando a mesma aquisição de fragmentos e o mesmo preâmbulo. O patch afeta quatro seleções somente no TARGET_PRODUCT Vortex.','','Pendências antes de qualquer aprovação de imagem/boot:','']
md += ['- '+x['fact'] for x in report['open_before_image_or_boot']]
md += ['','Os resultados anteriores em historical-before-final-profile/ ficam preservados como históricos; suas observações sobre entradas ainda não adquiridas ou prefixo de fontes incompleto não descrevem este snapshot final.','',f"JSON integral: final-profile-review.json; SHA-256 {digest(R/'final-profile-review.json')}.",'']
(R/'FINAL_PROFILE_REVIEW.md').write_text('\n'.join(md))
manifest={str(p.relative_to(R)):digest(p) for p in [R/'final-profile-review.json',R/'FINAL_PROFILE_REVIEW.md',Path(__file__),R/'provisioning/provisioning-review.json',R/'provisioning/PROVISIONING_REVIEW.md']};(R/'final-profile-review.sha256.json').write_text(json.dumps(manifest,indent=2)+'\n')
print(json.dumps({'counts':report['counts'],'stock':stock,'sha256':manifest},indent=2))
